/*
 * Process GitHub data and build Claude API prompt
 * Filters PRs to merged, deduplicates, and formats data
 */
const commits = $items('Fetch Commits');
const issues = $items('Fetch Closed Issues');
const prs = $items('Fetch Closed PRs');

// Filter to only merged PRs from the past week
const oneWeekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const mergedPRs = prs.filter(pr => {
  const data = pr.json;
  return data.merged_at && new Date(data.merged_at) >= oneWeekAgo;
});

// Filter issues closed in the past week (GitHub 'since' on issues is updated_at, not closed_at)
const recentIssues = issues.filter(issue => {
  const data = issue.json;
  return data.closed_at && new Date(data.closed_at) >= oneWeekAgo && !data.pull_request; // exclude PRs
});

// Aggregate contributors
const contributorMap = {};
for (const c of commits) {
  const name = c.json?.commit?.author?.name || 'Unknown';
  contributorMap[name] = (contributorMap[name] || 0) + 1;
}
const topContributors = Object.entries(contributorMap)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, count]) => `- ${name}: ${count} commits`)
  .join('\n');

// Format commit list
const commitList = commits.slice(0, 50).map(c => {
  const sha = c.json?.sha?.substring(0, 7) || 'unknown';
  const msg = c.json?.commit?.message?.split('\n')[0] || 'no message';
  const author = c.json?.commit?.author?.name || 'Unknown';
  return `  - \`${sha}\` ${msg} (${author})`;
}).join('\n');

// Format issue list
const issueList = recentIssues.map(i => {
  const num = i.json?.number;
  const title = i.json?.title;
  return `  - #${num} ${title}`;
}).join('\n');

// Format PR list
const prList = mergedPRs.map(p => {
  const num = p.json?.number;
  const title = p.json?.title;
  const additions = p.json?.additions || 0;
  const deletions = p.json?.deletions || 0;
  return `  - #${num} ${title} (+${additions}/-${deletions})`;
}).join('\n');

const repo = $vars.GITHUB_REPO || 'owner/repo';
const periodStart = oneWeekAgo.toISOString().split('T')[0];
const periodEnd = new Date().toISOString().split('T')[0];
const lang = ($vars.OUTPUT_LANGUAGE || 'EN').toUpperCase();

const systemPrompt = `You are a senior engineering manager writing a weekly development summary. Write in ${lang === 'FR' ? 'French' : 'English'}. Be concise, professional, and insightful. Use Markdown formatting.`;

const userPrompt = `## Repository: ${repo}
## Week: ${periodStart} → ${periodEnd}

### Commits (${commits.length} total)
${commitList || '  No commits this week.'}

### Issues Closed (${recentIssues.length} total)
${issueList || '  No issues closed this week.'}

### Pull Requests Merged (${mergedPRs.length} total)
${prList || '  No PRs merged this week.'}

### Top Contributors
${topContributors || '  No contributor data.'}

---

Write a weekly dev summary with these sections:
1. **Executive Summary** (2-3 sentences)
2. **Key Changes** (group related work into themes, bullet points)
3. **Issues Resolved** (highlight impactful issues)
4. **Contributor Spotlight** (recognize top contributors)
5. **Looking Ahead** (suggest focus areas based on patterns)`;

return [{
  json: {
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    repo,
    period_start: periodStart,
    period_end: periodEnd,
    stats: {
      commits: commits.length,
      issues_closed: recentIssues.length,
      prs_merged: mergedPRs.length
    }
  }
}];

/* Extract the generated text from Claude's response */
const response = $json;
const summaryText = response?.content?.[0]?.text || 'Error: No summary generated';

return [{
  json: {
    summary: summaryText,
    repo: $('Process & Build Prompt').item.json.repo,
    period_start: $('Process & Build Prompt').item.json.period_start,
    period_end: $('Process & Build Prompt').item.json.period_end,
    stats: $('Process & Build Prompt').item.json.stats
  }
}];

